```ts
import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
    const R = camera.limits.planetRadius;
    const lat = (latitudeDeg * Math.PI) / 180;
    const lon = (longitudeDeg * Math.PI) / 180;
    camera.center = {
        x: R * Math.cos(lat) * Math.cos(lon),
        y: -R * Math.cos(lat) * Math.sin(lon),
        z: R * Math.sin(lat),
    };
}
```

I placed the surface point using the coordinate convention from the notes (default centre at +X for lat 0/lon 0, north = +Z, east = −Y) and assigned a fresh object to `camera.center` so the camera re-orbits immediately rather than waiting for a later yaw/pitch/radius write. I'm not sure whether the library's `Vec3` type carries any extra fields beyond `x`, `y`, `z`, but the type declarations and notes treat it as a plain `{x, y, z}` object.
